import { createElement, type CSSProperties, type ReactNode } from "react";
import { mix } from "./schoolBoy";

// Students from clipart: eight in a school uniform (boys with a pencil, reading, with an apple, with
// a book; girls with a globe, a backpack, a paper, and pointing up) and one boy jumping for joy.
// The shapes are the original ones; the element color goes on the clothes and shoes (see
// uniformColors and hoorayColors). Skin, hair, faces, and the things they hold keep their colors.
// The four girls are "Designed by gstudioimagen / Freepik" (their free license asks for this credit).

type Props = { [key: string]: string | number | CSSProperties };
type Node = [tag: string, props: Props, children?: Node[]];

const isHex = (color: string) => /^#[0-9a-f]{6}$/i.test(color);

// Each clothing color in the clipart, and what it becomes for the element color.
function uniformColors(color: string): Record<string, string> {
  // A gradient ("url(#…)") can't be mixed, so it goes on the shorts, tie, and collar only.
  if (!isHex(color)) return { "#435C88": color, "#3C537C": color };
  return {
    "#435C88": color, // shorts or skirt, tie, collar
    "#3C537C": mix(color, -0.15), // their shading, and shoes
    "#F1F2F2": mix(color, 0.9), // shirt
    "#E6E7E8": mix(color, 0.8), // shirt shading
    "#D1D3D4": mix(color, 0.65), // soles
  };
}

function hoorayColors(color: string): Record<string, string> {
  if (!isHex(color)) return { "#EC641B": color, "#E94E1C": color };
  return {
    "#EC641B": color, // shorts
    "#E94E1C": mix(color, -0.08), // shorts shading
    "#E6301C": mix(color, -0.15),
    "#EA591C": color, // shoes
    "#C14315": mix(color, -0.25), // shoe edges
    "#511B00": mix(color, -0.7), // soles
    "#F3ECDE": mix(color, 0.88), // shirt and socks
    "#E2D9BF": mix(color, 0.78), // their shading
  };
}

// Draw the nodes, swapping clothing colors. A solid shape also gets a thin outline in its own
// color, which closes the hairline gaps where shapes meet.
function draw(nodes: Node[], colors: Record<string, string>): ReactNode[] {
  return nodes.map(([tag, props, children], i) => {
    const fill = typeof props.fill === "string" ? (colors[props.fill] ?? props.fill) : props.fill;
    const stroke = typeof props.stroke === "string" ? (colors[props.stroke] ?? props.stroke) : props.stroke;
    const seal = tag !== "g" && fill !== "none" && !stroke && props.opacity === undefined && !props.style;
    return createElement(
      tag,
      { key: i, ...props, fill, stroke: seal ? (fill ?? "#000") : stroke, strokeWidth: seal ? 1.2 : props.strokeWidth },
      children && draw(children, colors),
    );
  });
}

